from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class CellCMV1(SchemaObject):
    cell_id = SchemaField(name="cell_id")
    operational_state = SchemaField(name="operational_state")

    def __init__(self, cell_id, operational_state):
        self.cell_id = cell_id
        self.operational_state = operational_state

        super(CellCMV1, self).__init__()
